                if (tmp == NULL) {
                    return NULL;
                }
                strncpy(tmp + tmp_offset, orig + from, gap);
                tmp_offset += gap;
            }

            inx_start = inx_start2;
        }

        /* Set position for copying content after last match */
        from = inx_start + search_len;
